// === Tab: mySketch ===
/**
 * For the #WCCChallenge << Don't touch >>
 * Simulation of water, oil and neutral particles
 * Based on https://openprocessing.org/sketch/43171, credit to Tim Hutton
 *
 * Particles have two forces: a strong force repelling water and oil, and a weak one repelling every other type of particle
 * (same type repel as well), so none of them are touching but constantly moving.
 * Perhaps I create a version with changeable parameters later
 */

// Original by Tim Hutton (2011) <tim.hutton@gmail.com> - http://www.sq3.org.uk

// A model of oil-water phase separation
// Based on Naoaki Ono's PhD thesis

OPC.slider('PARTICLE_SIZE', 15, 10, 20, 1)

OPC.slider('STRONG_FORCE_RANGE_MULTIPLIER', 10, 5, 20, 1) 
OPC.slider('MEDIUM_FORCE_RANGE_MULTIPLIER', 3, 1, 5, 1)
OPC.slider('STRONG_FORCE_MAGNITUDE', 0.02, 0.005, 0.04, 0.005) // Repel force between water and oil particles
OPC.slider('MEDIUM_FORCE_MAGNITUDE', 0.2, 0.05, 0.4, 0.05) // Repel force between any other two particles
OPC.slider('MAX_SPEED_MULTIPLIER', 0.3, 0.1, 0.5, 0.05)
OPC.toggle('constrain_angle', true)
OPC.slider('move_angle', 90, 15, 90, 5)
OPC.palette('palette', [
  ["#000000","#1DA1F2", "#FFEF04", "#FFFFFF" ],
	["#0a0a0a", "#0077e1", "#fc3503", "#f5d216"],
  ["#6d358a", "#218ad4", "#d33033", "#00953c"],
  ["#3f7373", "#77d9d9", "#f0de84", "#63991f"]
])
OPC.slider('drawType', 0, 0, 2, 1)
OPC.slider('alphaTrail', 60, 0, 255, 5)

let STRONG_FORCE_RANGE, MEDIUM_FORCE_RANGE

const WATER = 0
const HYDROPHOBIC = 1
const NEUTRAL = 2

let MAX_SPEED // = 0.25 * R

let atoms = []
let N_ATOMS
let cw = 1000
let ch = 1000
let paletteAlpha
let bgColor, bgColorAlpha

function _reset () {
	STRONG_FORCE_RANGE = STRONG_FORCE_RANGE_MULTIPLIER * PARTICLE_SIZE
	MEDIUM_FORCE_RANGE = MEDIUM_FORCE_RANGE_MULTIPLIER * PARTICLE_SIZE
	MAX_SPEED = MAX_SPEED_MULTIPLIER * PARTICLE_SIZE
  bgColor = palette[0]
  bgColorAlpha = color(bgColor)
  bgColorAlpha.setAlpha(alphaTrail) // Set alpha to leave a "trail"
  paletteAlpha = palette.map((c) => {
    let a = color(c)
    a.setAlpha(30)
    return a
  })

  N_ATOMS = 150
  atoms = []
  for (let i = 0; i < N_ATOMS; i++) {
    atoms.push(
      new Atom(random() < 0.2 ? HYDROPHOBIC : random() < 0.8 ? WATER : NEUTRAL)
    )
  }
}

function setup() {
  createCanvas(cw, ch)
  _reset()
}

function draw() {
  // update the positions
  recomputeAccelerations()
  recomputeVelocities()
  recomputePositions()
  // draw
  background(bgColorAlpha)

  for (let i = 0; i < N_ATOMS; i++) {
    atoms[i].drawAtom()
  }
  // draw the mouse-controlled water atom
  stroke(palette[1])
  strokeWeight(3)
  noFill()

}

function recomputeAccelerations() {
  for (let i = 0; i < N_ATOMS; i++) {
    atoms[i].acceleration.x = atoms[i].acceleration.y = 0
  }

  let d, f
  let force, to
  for (let i = 0; i < N_ATOMS; i++) {
    for (let j = i + 1; j < N_ATOMS; j++) {
      to = p5.Vector.sub(atoms[i].position, atoms[j].position)
      d = to.mag()

      // apply repulsion forces between this pair of atoms
      if (d < STRONG_FORCE_RANGE) {
        if (
          (atoms[i].type === WATER && atoms[j].type === HYDROPHOBIC) ||
          (atoms[i].type === HYDROPHOBIC && atoms[j].type === WATER)
        ) {
          // strong repulsion
          f = repulsion_force(STRONG_FORCE_RANGE, d, STRONG_FORCE_MAGNITUDE)
        } else {
          // medium repulsion
          f = repulsion_force(MEDIUM_FORCE_RANGE, d, MEDIUM_FORCE_MAGNITUDE)
        }
        force = p5.Vector.mult(to, f)
        atoms[i].acceleration.add(force)
        atoms[j].acceleration.sub(force)
      }
    }

    // atoms are repelled by the walls
    for (let wall_test = 0; wall_test < 4; wall_test++) {
      // pretend there's a water atom at the nearby wall, repelling us
      let wall
      switch (wall_test) {
        default:
        case 0:
          wall = createVector(0, atoms[i].position.y)
          break
        case 1:
          wall = createVector(width, atoms[i].position.y)
          break
        case 2:
          wall = createVector(atoms[i].position.x, 0)
          break
        case 3:
          wall = createVector(atoms[i].position.x, height)
          break
      }
      to = p5.Vector.sub(atoms[i].position, wall)
      switch (atoms[i].type) {
        case WATER:
          f = repulsion_force(
            MEDIUM_FORCE_RANGE,
            to.mag(),
            MEDIUM_FORCE_MAGNITUDE
          )
          break
        default:
          f = repulsion_force(
            STRONG_FORCE_RANGE,
            to.mag(),
            STRONG_FORCE_MAGNITUDE
          )
          break
      }
      atoms[i].acceleration.add(p5.Vector.mult(to, f))
    }


  }
}

function recomputeVelocities() {
  for (let i = 0; i < N_ATOMS; i++) {
    atoms[i].velocity.add(atoms[i].acceleration)
    atoms[i].velocity.limit(MAX_SPEED)
		if (constrain_angle) {
	    atoms[i].velocity = roundVelocityToMultiples(atoms[i].velocity, radians(move_angle))
		}
  }
}

function exponentialMap(value, start1, stop1, start2, stop2, exp) {
  const exponentialValue = Math.pow(value / stop1, exp);
  return start2 + (stop2 - start2) * exponentialValue;
}

function roundVelocityToMultiples(velocity, roundAngle = PI / 6) {
  const angle = velocity.heading()
  const roundedAngle = Math.round(angle / roundAngle) * roundAngle
  const magnitude = velocity.mag()
  const roundedVelocity = p5.Vector.fromAngle(roundedAngle)
  roundedVelocity.setMag(magnitude)
  return roundedVelocity
}

function recomputePositions() {
  for (let i = 0; i < N_ATOMS; i++) {
    atoms[i].position.add(atoms[i].velocity)
    if (atoms[i].position.x < 0) atoms[i].position.x = MEDIUM_FORCE_RANGE
    if (atoms[i].position.x > width)
      atoms[i].position.x = width - MEDIUM_FORCE_RANGE
    if (atoms[i].position.y < 0) atoms[i].position.y = MEDIUM_FORCE_RANGE
    if (atoms[i].position.y > height)
      atoms[i].position.y = height - MEDIUM_FORCE_RANGE
  }
}

function repulsion_force(range, d, magnitude) {
  d = Math.max(d, 0.1)
  if (d < range) {
    return magnitude * (range / d - 1)
  } else {
    return 0
  }
}


// -------------------------- Atom -----------------------------

class Atom {
  constructor(t) {
    this.position = createVector(random(width), random(height))
    this.velocity = createVector(random(-3, 3), random(-3, 3))
    this.acceleration = createVector()
    this.type = t
    switch (this.type) {
      case WATER:
        this.color = palette[1]
        this.colorAlpha = paletteAlpha[1]
        break
      case HYDROPHOBIC:
        this.color = palette[2]
        this.colorAlpha = paletteAlpha[2]
        break
      case NEUTRAL:
        this.color = palette[3]
        this.colorAlpha = paletteAlpha[3]
        break
    }
  }

  drawAtom() {
    fill(this.colorAlpha)

    switch (drawType) {
      case 0: // Circle
        // stroke(this.colorAlpha)
        // fill(this.color)
        // circle(this.position.x, this.position.y, PARTICLE_SIZE * 1.2)

				fill(this.color);
				noStroke();
    		for (let i = 0; i < 8; i++) {circle(this.position.x+PARTICLE_SIZE * 0.6 * cos(PI / 4 * i),this.position.y+PARTICLE_SIZE * 0.6 * sin(PI / 4 * i), PARTICLE_SIZE * 0.6);}
        circle(this.position.x,this.position.y, PARTICLE_SIZE * 0.9);


  // rotate(225);
  // fill(255);
  // rect(this.position.x,this.position.y, 10, 40);
  // rotate(-90);
  // rect(this.position.x,this.position.y, 10, 30);

				break
      }
    }
}

function parameterChanged () {
	_reset()
}

